#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 105;

struct Data {
    int s, t, d, id;
} a[N];

int ans[N], prepared[N], exam[N];
int n, m;

bool comp(const Data& x, const Data& y) {
    return x.t < y.t;
}

int main() {
    scanf("%d%d", &n, &m);

    for (int i = 1; i <= m; ++i) {
        scanf("%d%d%d", &a[i].s, &a[i].t, &a[i].d);
        a[i].id = i;
    }

    sort(a + 1, a + m + 1, comp);

    for (int i = 1; i <= m; ++i)
        exam[a[i].t] = i;

    for (int day = 1; day <= n; ++day) {
        if (exam[day]) {
            int i = exam[day];
            if (prepared[i] != a[i].d) {
                puts("-1");
                return 0;
            }
            ans[day] = m + 1;
            continue;
        }

        for (int i = 1; i <= m; ++i) {
            if (prepared[i] < a[i].d && day >= a[i].s) {
                ans[day] = a[i].id;
                ++prepared[i];
                break;
            }
        }
    }

    for (int i = 1; i <= n; ++i)
        printf("%d%c", ans[i], i == n ? '\n' : ' ');

    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 105;

struct Data {
    int s, t, d, id;
} a[N];

int ans[N], used[N], num[N], n, m;

inline int nextChar() {
    static char buffer[100000];
    static size_t pos = 0, len = 0;

    if (pos == len) {
        len = fread(buffer, 1, sizeof(buffer), stdin);
        pos = 0;
        if (len == 0) return EOF;
    }
    return buffer[pos++];
}

inline bool readInt(int& x) {
    int ch;
    do {
        ch = nextChar();
        if (ch == EOF) return false;
    } while (ch < '0' || ch > '9');

    x = 0;
    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = nextChar();
    }
    return true;
}

inline bool comp(const Data& x, const Data& y) {
    return x.t < y.t;
}

int main() {
    if (!readInt(n) || !readInt(m)) return 0;

    for (int i = 1; i <= m; ++i) {
        readInt(a[i].s);
        readInt(a[i].t);
        readInt(a[i].d);
        a[i].id = i;
    }

    sort(a + 1, a + m + 1, comp);

    for (int i = 1; i <= m; ++i)
        num[a[i].t] = i;

    for (int i = 1; i <= n; ++i) {
        if (num[i]) {
            if (used[num[i]] == a[num[i]].d) {
                ans[i] = m + 1;
                continue;
            }
            puts("-1");
            return 0;
        }

        for (int j = 1; j <= m; ++j) {
            if (used[j] != a[j].d && i >= a[j].s) {
                ans[i] = a[j].id;
                ++used[j];
                break;
            }
        }
    }

    for (int i = 1; i <= n; ++i)
        printf("%d ", ans[i]);

    return 0;
}

